// Form data extract karo
let masterSheetIdRaw = $input.first().json['Master Google Sheet ID or Full URL'] || '';
let masterSheetId = masterSheetIdRaw.trim();

// Auto-extract ID if full URL is pasted
if (masterSheetId.includes('/d/')) {
  masterSheetId = masterSheetId.split('/d/')[1].split('/')[0];
}

const city = $input.first().json['City / State'] || '';
const country = $input.first().json['Country'] || '';
const niche = $input.first().json['Niche / Industry'] || '';
const customQuestions = $input.first().json['Custom Questions / Query Guidelines'] || '';
const sourcesChoice = $input.first().json['Sources to Search'] || 'All Platforms (24h Filter)';

// Tab Name build karo (e.g., Real Estate - Houston)
const tabName = `${niche} - ${city}`.slice(0, 30); // Max 30 chars for tab safety

// Reddit search query build karo
const searchQuery = `${niche} ${city} ${country}`;
const redditQuery = encodeURIComponent(searchQuery);
const redditUrl = `https://www.reddit.com/search.rss?q=${redditQuery}&sort=new&t=day`;

// 24h Filtered Search URLs for platforms
const linkedin24hUrl = `https://www.google.com/search?q=site:linkedin.com/posts+${encodeURIComponent(`${niche} ${city} ${country}`)}&tbs=qdr:d`;
const reddit24hWebUrl = `https://www.reddit.com/search/?q=${encodeURIComponent(`${niche} ${city} ${country}`)}&t=day&sort=new`;
const googleMapsUrl = `https://www.google.com/maps/search/${encodeURIComponent(`${niche} ${city} ${country}`)}`;
const facebook24hUrl = `https://www.google.com/search?q=site:facebook.com+${encodeURIComponent(`${niche} ${city}`)}&tbs=qdr:d`;
const generalForums24hUrl = `https://www.google.com/search?q=${encodeURIComponent(`"${niche}" "${city}" ("help" OR "question" OR "looking for" OR "recommendation")`)}&tbs=qdr:d`;

// Custom questions parse karo
const questionsList = customQuestions
  .split('\n')
  .map(q => q.trim())
  .filter(q => q.length > 0);

const questionsStr = questionsList.length > 0
  ? questionsList.map((q, i) => `Q${i+1}: ${q}`).join(' | ')
  : 'None';

const timestamp = new Date().toISOString();

return [
  {
    json: {
      masterSheetId,
      tabName,
      city,
      country,
      niche,
      questionsStr,
      sourcesChoice,
      redditUrl,
      searchQuery,
      linkedin24hUrl,
      reddit24hWebUrl,
      googleMapsUrl,
      facebook24hUrl,
      generalForums24hUrl,
      timestamp
    }
  }
];

// Response parse karo aur har post / link ke liye ALAG ROW ITEM create karo
const inputData = $input.first().json || {};
const prevData = $('Build Search Data').first().json;
const sourceChoice = prevData.sourcesChoice || 'All Platforms (24h Filter)';

const rowItems = [];

// 1. Reddit Posts Parse (If selected)
if (sourceChoice.includes('Reddit') || sourceChoice.includes('All')) {
  let rawXml = '';
  if (typeof inputData === 'string') {
    rawXml = inputData;
  } else if (inputData.data) {
    rawXml = typeof inputData.data === 'string' ? inputData.data : JSON.stringify(inputData.data);
  } else {
    rawXml = JSON.stringify(inputData);
  }

  const entryRegex = /<entry>[\s\S]*?<title>(.*?)<\/title>[\s\S]*?<link [^>]*href="(.*?)"[\s\S]*?<updated>(.*?)<\/updated>[\s\S]*?<\/entry>/gi;
  let match;
  let count = 0;

  while ((match = entryRegex.exec(rawXml)) !== null && count < 10) {
    count++;
    let title = match[1]
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&#39;/g, "'")
      .replace(/&quot;/g, '"');
    const url = match[2];
    const updated = match[3];
    const postDate = new Date(updated);
    const hoursAgo = Math.max(0, Math.round((Date.now() - postDate.getTime()) / (1000 * 60 * 60)));

    rowItems.push({
      json: {
        MasterSheetId: prevData.masterSheetId,
        TabName: prevData.tabName,
        Title: title,
        'Post / Link': url,
        Platform: 'Reddit',
        'Posted Time': `${hoursAgo} hours ago`,
        City: prevData.city,
        Country: prevData.country,
        Niche: prevData.niche,
        'Custom Questions': prevData.questionsStr
      }
    });
  }

  // Backup link row for Reddit search if no direct RSS entries matched
  if (count === 0) {
    rowItems.push({
      json: {
        MasterSheetId: prevData.masterSheetId,
        TabName: prevData.tabName,
        Title: `Reddit 24h Search Feed (${prevData.niche} - ${prevData.city})`,
        'Post / Link': prevData.reddit24hWebUrl,
        Platform: 'Reddit',
        'Posted Time': 'Past 24 Hours Search',
        City: prevData.city,
        Country: prevData.country,
        Niche: prevData.niche,
        'Custom Questions': prevData.questionsStr
      }
    });
  }
}

// 2. LinkedIn Search Link Row (If selected)
if (sourceChoice.includes('LinkedIn') || sourceChoice.includes('All')) {
  rowItems.push({
    json: {
      MasterSheetId: prevData.masterSheetId,
      TabName: prevData.tabName,
      Title: `LinkedIn 24h Posts Search (${prevData.niche} - ${prevData.city})`,
      'Post / Link': prevData.linkedin24hUrl,
      Platform: 'LinkedIn',
      'Posted Time': 'Past 24 Hours Search',
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Custom Questions': prevData.questionsStr
    }
  });
}

// 3. Facebook Search Link Row (If selected)
if (sourceChoice.includes('Facebook') || sourceChoice.includes('All')) {
  rowItems.push({
    json: {
      MasterSheetId: prevData.masterSheetId,
      TabName: prevData.tabName,
      Title: `Facebook 24h Posts Search (${prevData.niche} - ${prevData.city})`,
      'Post / Link': prevData.facebook24hUrl,
      Platform: 'Facebook',
      'Posted Time': 'Past 24 Hours Search',
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Custom Questions': prevData.questionsStr
    }
  });
}

// 4. General Forums Search Link Row (If selected)
if (sourceChoice.includes('Forums') || sourceChoice.includes('All')) {
  rowItems.push({
    json: {
      MasterSheetId: prevData.masterSheetId,
      TabName: prevData.tabName,
      Title: `General Forums 24h Queries Search (${prevData.niche} - ${prevData.city})`,
      'Post / Link': prevData.generalForums24hUrl,
      Platform: 'General Forums',
      'Posted Time': 'Past 24 Hours Search',
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Custom Questions': prevData.questionsStr
    }
  });
}

// 5. Google Maps Search Link Row (If selected)
if (sourceChoice.includes('Maps') || sourceChoice.includes('All')) {
  rowItems.push({
    json: {
      MasterSheetId: prevData.masterSheetId,
      TabName: prevData.tabName,
      Title: `Google Maps Businesses Search (${prevData.niche} - ${prevData.city})`,
      'Post / Link': prevData.googleMapsUrl,
      Platform: 'Google Maps',
      'Posted Time': 'Direct Business Search',
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Custom Questions': prevData.questionsStr
    }
  });
}

return rowItems;
